def f(g):
    a=np.array(g); H,W=a.shape; res=[]
    # solid rectangles of size>=2x2, keep maximal ones (not contained in another)
    cands=[]
    for r1 in range(H):
        for r2 in range(r1,H):
            for c1 in range(W):
                for c2 in range(c1,W):
                    blk=a[r1:r2+1,c1:c2+1]
                    if len({int(x) for x in blk.flatten()}-{0})==1 and blk.size>=4:
                        cands.append((int(blk[0,0]),blk.size))
    best=max(cands,key=lambda t:t[1])
    return [int(v) for v in a[a==best[0]].flatten()].__iter__()
