def comps(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=0 and not seen[i][j]:
                c=g[i][j]; stack=[(i,j)]; comp=[]
                while stack:
                    r2,cc=stack.pop()
                    if 0<=r2<H and 0<=cc<W and g[r2][cc]==c and not seen[r2][cc]:
                        seen[r2][cc]=True; comp.append((r2,cc))
                        stack+=[(r2+1,cc),(r2-1,cc),(r2,cc+1),(r2,cc-1)]
                rs=[a for a,b in comp]; cs=[b for a,b in comp]
                out.append((c,len(comp),max(rs)-min(rs)+1,max(cs)-min(cs)+1))
    return out
